<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRoute } from 'vue-router'
import ProductImageField from '../components/ProductImageField.vue'
import { filamentApi } from '../services/filamentApi'
import { locationApi } from '../services/locationApi'
import { emptySpool, editableSpool, emptyFilamentConfig, editableFilamentConfig } from '../types/filament'
import type { FilamentSettings, FilamentSlot, FilamentSpool } from '../types/filament'
import type { LocationTreeNode } from '../types/locations'

const route = useRoute()
const tab = ref('collection'), loading = ref(true), busy = ref(false), error = ref(''), info = ref('')
const items = ref<FilamentSpool[]>([]), slots = ref<FilamentSlot[]>([]), settings = ref<FilamentSettings | null>(null)
const config = ref(emptyFilamentConfig()), savedConfig = ref('')
const serialText = computed({ get: () => config.value.printer_serials.join('\n'), set: (v: string) => { config.value.printer_serials = v.split(/[\n,]+/).map(v => v.trim()).filter(Boolean) } })
const login = ref({ account: '', password: '', code: '', access_token: '' }), verify = ref(false)
const query = ref(''), material = ref<string | null>(null), manufacturer = ref<string | null>(null), condition = ref<string | null>(null)
const archive = ref('active'), reorder = ref(false), amsOnly = ref(false)
const selected = ref<string[]>([]), failedImages = ref(new Set<string>())
const editor = ref(false), editing = ref<string | null>(null), form = ref(emptySpool()), savedForm = ref('')
const detail = ref<FilamentSpool | null>(null), archiving = ref<FilamentSpool | null>(null), cloudDelete = ref(false)
const binding = ref<FilamentSlot | null>(null), bindingId = ref<string | null>(null)
const locations = ref<{ title: string, value: string }[]>([])
const materials = computed(() => [...new Set(['PLA','PETG','ABS','ASA','TPU','PA','PC',...items.value.map(v => v.material)])].sort())
const manufacturers = computed(() => [...new Set(items.value.map(v => v.manufacturer).filter(Boolean))].sort())
const visible = computed(() => items.value.filter(v => (archive.value === 'all' || (archive.value === 'archived' ? !!v.archived_at : !v.archived_at)) && (!material.value || v.material === material.value) && (!manufacturer.value || v.manufacturer === manufacturer.value) && (!condition.value || v.condition === condition.value) && (!reorder.value || v.reorder) && (!amsOnly.value || v.slot_id !== null) && [v.label_code,v.manufacturer,v.material,v.variant,v.color_name,v.shop_code,v.rfid,v.cloud_id].join(' ').toLocaleLowerCase().includes((query.value || '').toLocaleLowerCase())))
const active = computed(() => items.value.filter(v => !v.archived_at))
const totalG = computed(() => active.value.reduce((sum, v) => sum + (v.remaining_g ?? 0), 0))
const missingG = computed(() => active.value.filter(v => v.remaining_g === null).length)
const dirty = computed(() => !loading.value && ((editor.value && JSON.stringify(form.value) !== savedForm.value) || JSON.stringify(config.value) !== savedConfig.value || Object.values(login.value).some(Boolean)))
const number = (value: number) => value.toLocaleString('de-DE', { maximumFractionDigits: 1 })
const time = (value: string | null) => value ? new Date(value.endsWith('Z') || /[+-]\d{2}:\d{2}$/.test(value) ? value : value + 'Z').toLocaleString('de-DE') : 'Noch nicht erkannt'
const liveSlot = (v: FilamentSlot) => Date.now() - new Date(v.observed_at.endsWith('Z') ? v.observed_at : v.observed_at + 'Z').getTime() < 10 * 60 * 1000
async function action(operation: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; info.value = ''; try { await operation() } catch (e) { error.value = e instanceof Error ? e.message : 'Aktion fehlgeschlagen' } finally { busy.value = false } }
async function load() { const [rolls, observed, current] = await Promise.all([filamentApi.list(),filamentApi.slots(),filamentApi.settings()]); items.value = rolls; slots.value = observed; settings.value = current; if (!savedConfig.value) { config.value = editableFilamentConfig(current); savedConfig.value = JSON.stringify(config.value) } }
function flatten(nodes: LocationTreeNode[]): { title: string, value: string }[] { return nodes.flatMap(n => [{ title: n.path || n.name, value: n.id }, ...flatten(n.children)]) }
async function showRoute() { if (typeof route.params.id === 'string') { try { detail.value = await filamentApi.get(route.params.id) } catch (e) { error.value = e instanceof Error ? e.message : 'Rolle nicht gefunden' } } }
onMounted(async () => { try { await load(); locations.value = flatten(await locationApi.tree()); await showRoute() } catch (e) { error.value = e instanceof Error ? e.message : 'Modul konnte nicht geladen werden' } finally { loading.value = false } })
watch(() => route.params.id, showRoute)
function open(row?: FilamentSpool) { detail.value = null; editing.value = row?.id ?? null; form.value = row ? editableSpool(row) : emptySpool(); savedForm.value = JSON.stringify(form.value); editor.value = true }
function closeEditor() { if (!busy.value && (JSON.stringify(form.value) === savedForm.value || window.confirm('Ungespeicherte Rollenangaben verwerfen?'))) editor.value = false }
async function save() { await action(async () => { const data = { ...form.value }; for (const key of ['initial_g','remaining_g','remaining_percent'] as const) data[key] = data[key] === null || String(data[key]) === '' ? null : Number(data[key]); if (editing.value) await filamentApi.update(editing.value,data); else await filamentApi.create(data); editor.value = false; await load(); info.value = 'Rolle gespeichert' }) }
function pickArchive(row: FilamentSpool) { archiving.value = row; cloudDelete.value = false }
async function archiveNow() { await action(async () => { if (!archiving.value) return; const result = await filamentApi.archive(archiving.value.id,cloudDelete.value); archiving.value = null; detail.value = null; await load(); info.value = result.warning || 'Rolle archiviert' }) }
async function restore(row: FilamentSpool) { await action(async () => { await filamentApi.restore(row.id); detail.value = null; await load() }) }
async function exportLabels(format: 'pdf' | 'jpg') { await action(async () => { const { blob,filename } = await filamentApi.labels(selected.value,format); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = filename; link.click(); setTimeout(() => URL.revokeObjectURL(url),10000) }) }
async function saveConfig() { await action(async () => { settings.value = await filamentApi.saveSettings(config.value); config.value = editableFilamentConfig(settings.value); savedConfig.value = JSON.stringify(config.value); info.value = 'Filament-Einstellungen gespeichert' }) }
function discardConfig() { if (settings.value && window.confirm('Ungespeicherte Verbindungseinstellungen verwerfen?')) { config.value = editableFilamentConfig(settings.value); savedConfig.value = JSON.stringify(config.value); login.value = { account: '',password: '',code: '',access_token: '' } } }
async function connect() { await action(async () => { const draft = editableFilamentConfig(config.value); const result = await filamentApi.login({ ...login.value, account: login.value.account || 'token', region: config.value.region, password: login.value.password || null, code: login.value.code || null, access_token: login.value.access_token || null }); login.value.password = ''; login.value.code = ''; login.value.access_token = ''; verify.value = result.verification_required; if (result.connected) { login.value.account = ''; savedConfig.value = ''; await load(); config.value = { ...draft, enabled: false }; info.value = 'Bambu verbunden. Automatischen Sync bei Bedarf aktivieren und speichern.' } else info.value = 'Bambu verlangt den E-Mail-Code. Code eingeben und erneut anmelden.' }) }
async function disconnect() { if (!window.confirm('Bambu-Verbindung trennen? Rollen und Archiv bleiben erhalten.')) return; await action(async () => { const draft = editableFilamentConfig(config.value); await filamentApi.disconnect(); savedConfig.value = ''; await load(); config.value = { ...draft, enabled: false } }) }
async function sync() { await action(async () => { const result = await filamentApi.sync(); await load(); info.value = result.warning || `${result.count} Cloud-Rollen abgeglichen` }) }
async function refreshSlots() { await action(async () => { const result = await filamentApi.refreshSlots(); await load(); info.value = `${result.slots} AMS-Slots empfangen${result.printers_missing.length ? '; ohne Antwort: ' + result.printers_missing.join(', ') : ''}` }) }
async function storeImage(row: FilamentSpool) { if (row.image_url && !window.confirm('Vorhandenes Bild durch ein eindeutig passendes Store-Bild ersetzen?')) return; await action(async () => { await filamentApi.storeImage(row.id); await load(); info.value = 'Farbbild lokal gespeichert' }) }
async function importFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; await action(async () => { if (file.size > 8 * 1024 * 1024) throw new Error('Importdatei maximal 8 MB'); const source = JSON.parse(await file.text()); await filamentApi.importSnapshot({ spools: source.spools || source.hits, complete: source.complete === true, account_reference: 'offline-import' }); await load(); info.value = source.complete === true ? 'Snapshot importiert' : 'Teilbestand importiert – keine Rollen als fehlend markiert' }); (event.target as HTMLInputElement).value = '' }
async function saveBinding() { await action(async () => { if (!binding.value) return; await filamentApi.bind(binding.value.id,bindingId.value); binding.value = null; await load() }) }
function unload(event: BeforeUnloadEvent) { if (dirty.value) { event.preventDefault(); event.returnValue = '' } }
window.addEventListener('beforeunload',unload); onBeforeUnmount(() => window.removeEventListener('beforeunload',unload))
onBeforeRouteLeave(() => !busy.value && (!dirty.value || window.confirm('Ungespeicherte Filamentangaben verwerfen und Seite verlassen?')))
</script>

<template>
  <v-container class="filament-page py-6" fluid>
    <div class="d-flex flex-wrap ga-3 align-center mb-5"><div><h1>Filament-Sammlung</h1><p class="text-medium-emphasis">Rollenbestand, Restmengen und AMS-Zuordnung</p></div><v-spacer /><v-btn to="/wiki/handbuch" variant="text">Handbuch</v-btn><v-btn :disabled="busy" variant="text" @click="action(load)">Aktualisieren</v-btn><v-btn color="primary" prepend-icon="mdi-plus" :disabled="busy" @click="open()">Rolle erfassen</v-btn></div>
    <v-alert v-if="error" type="error" class="mb-4">{{ error }}</v-alert><v-alert v-if="info" type="info" class="mb-4">{{ info }}</v-alert>
    <v-progress-linear v-if="loading || busy" indeterminate class="mb-4" />
    <v-row class="mb-3"><v-col cols="12" sm="4"><v-card><v-card-text><div>Aktive Rollen</div><div class="text-h4">{{ active.length }}</div><span class="text-medium-emphasis">{{ items.length - active.length }} archiviert</span></v-card-text></v-card></v-col><v-col cols="12" sm="4"><v-card><v-card-text><div>Erfasste Restmenge</div><div class="text-h4">{{ number(totalG / 1000) }} kg</div><span class="text-medium-emphasis">{{ missingG }} unbekannt · Cloudwerte sind Schätzungen</span></v-card-text></v-card></v-col><v-col cols="12" sm="4"><v-card><v-card-text><div>Zum Nachbestellen markiert</div><div class="text-h4">{{ active.filter(v => v.reorder).length }}</div><span class="text-medium-emphasis">Aktiver Bestand · keine automatische Bestellung</span></v-card-text></v-card></v-col></v-row>
    <v-tabs v-model="tab" class="mb-4"><v-tab value="collection">Rollenbestand</v-tab><v-tab value="ams">AMS-Belegung</v-tab><v-tab value="settings">Bambu & Einstellungen</v-tab></v-tabs>
    <template v-if="tab === 'collection'">
      <v-row dense><v-col cols="12" md="4"><v-text-field v-model="query" label="Rollen-ID, Farbe, Material oder Shopnummer suchen" clearable /></v-col><v-col cols="6" md="2"><v-select v-model="material" :items="materials" label="Material" clearable /></v-col><v-col cols="6" md="2"><v-select v-model="manufacturer" :items="manufacturers" label="Hersteller" clearable /></v-col><v-col cols="6" md="2"><v-select v-model="condition" :items="[{title:'Eingepackt',value:'sealed'},{title:'Offen',value:'open'}]" label="Zustand" clearable /></v-col><v-col cols="6" md="2"><v-select v-model="archive" :items="[{title:'Aktiv',value:'active'},{title:'Archiv',value:'archived'},{title:'Alle',value:'all'}]" label="Bestand" /></v-col></v-row>
      <div class="d-flex flex-wrap ga-3 align-center mb-4"><v-checkbox v-model="reorder" label="Nur Nachbestellungen" hide-details /><v-checkbox v-model="amsOnly" label="Nur mit AMS-Zuordnung" hide-details /><v-spacer /><span>{{ visible.length }} Rollen · {{ selected.length }} ausgewählt</span><v-btn :disabled="busy || !selected.length" @click="exportLabels('pdf')">PDF 40 × 30 mm</v-btn><v-btn :disabled="busy || !selected.length" @click="exportLabels('jpg')">JPG-Etiketten</v-btn><v-btn variant="text" @click="selected = visible.slice(0,100).map(v => v.id)">Sichtbare auswählen (max. 100)</v-btn><v-btn variant="text" @click="selected = []">Auswahl leeren</v-btn></div>
      <v-alert v-if="!visible.length && !loading" variant="tonal" type="info">{{ items.length ? 'Keine passenden Rollen. Filter anpassen.' : 'Erfasse deine erste Rolle manuell oder verbinde deinen Bambu-Bestand.' }}</v-alert>
      <v-row><v-col v-for="row in visible" :key="row.id" cols="12" sm="6" lg="4" xl="3"><v-card rounded="lg" height="100%"><v-img v-if="row.image_url && !failedImages.has(row.id)" :src="row.image_url" height="160" contain @error="failedImages.add(row.id)" /><div v-else class="spool-placeholder" :style="{ '--spool-color': row.color_hex.slice(0,7) }"><div class="spool-disc"><span>{{ row.material }}</span></div></div><v-card-text><div class="d-flex align-center"><span class="text-medium-emphasis">{{ row.label_code }}</span><v-spacer /><v-checkbox v-model="selected" :value="row.id" :aria-label="`${row.label_code} für Etiketten auswählen`" hide-details density="compact" /></div><h2 class="text-h6">{{ row.manufacturer || 'Unbekannter Hersteller' }} · {{ row.variant || row.material }}</h2><div>{{ row.color_name || row.color_hex }}{{ row.shop_code ? ' · ' + row.shop_code : '' }}</div><div class="d-flex flex-wrap ga-2 my-2"><v-chip size="small">{{ row.condition === 'open' ? 'Offen' : 'Eingepackt' }}</v-chip><v-chip v-if="row.reorder" size="small" color="warning">Nachbestellen</v-chip><v-chip v-if="row.archived_at" size="small">Archiv</v-chip></div><p>{{ row.remaining_g === null ? 'Restgewicht unbekannt' : number(row.remaining_g) + ' g verbleibend' }}{{ row.remaining_percent === null ? '' : ' · ' + number(row.remaining_percent) + ' %' }}</p><v-progress-linear v-if="row.remaining_percent !== null" :model-value="row.remaining_percent" class="my-2" rounded /><p>{{ row.location_name || row.storage_note || 'Kein Lagerort' }}</p><p v-if="row.slot_id !== null" class="text-medium-emphasis">{{ row.printer_serial || 'Cloud-Drucker' }} · AMS {{ row.ams_id }} / Slot {{ row.slot_id }} · {{ row.mount_source === 'cloud' ? 'Cloud-Zuordnung, nicht live' : 'letzter Snapshot' }}</p><p class="text-medium-emphasis">Zuletzt erkannt: {{ time(row.last_seen_at) }}</p><p v-if="row.cloud_present === false" class="text-medium-emphasis">In der Cloud nicht mehr vorhanden</p><p v-if="row.image_url && !row.image_verified" class="text-medium-emphasis">Bild manuell / Zuordnung ungeprüft</p></v-card-text><v-card-actions class="flex-wrap"><v-btn @click="detail = row">Details</v-btn><v-btn @click="open(row)">Bearbeiten</v-btn><v-spacer /><v-btn v-if="row.archived_at" :disabled="busy" @click="restore(row)">Wiederherstellen</v-btn><v-btn v-else :disabled="busy" @click="pickArchive(row)">Archivieren</v-btn></v-card-actions></v-card></v-col></v-row>
    </template>
    <template v-if="tab === 'ams'"><div class="d-flex flex-wrap align-center ga-3 mb-4"><p>Beobachtete Belegung; ausgegraute Zeitangaben sind keine Live-Zusage.</p><v-spacer /><v-btn :disabled="busy" @click="refreshSlots">AMS aus Cloud-MQTT abrufen</v-btn></div><v-alert v-if="settings?.mqtt_error" type="warning" class="mb-3">{{ settings.mqtt_error }}</v-alert><v-alert v-if="!slots.length" type="info" variant="tonal">Für AMS-Snapshots Bambu anmelden und die Druckerkennungen unter Einstellungen hinterlegen.</v-alert><v-row><v-col v-for="slot in slots" :key="slot.id" cols="12" sm="6" lg="4"><v-card><v-card-title class="text-wrap">{{ slot.printer_serial }} · AMS {{ slot.ams_id }} / Slot {{ slot.slot_id }}</v-card-title><v-card-text><v-chip :color="liveSlot(slot) ? 'success' : undefined">{{ liveSlot(slot) ? 'Snapshot jünger als 10 Minuten' : 'Alter Snapshot' }}</v-chip><p class="mt-3">{{ slot.occupied ? slot.spool_label || 'Belegt · Rolle nicht eindeutig zugeordnet' : 'Zuletzt leer gemeldet' }}</p><p>{{ slot.material }} · {{ slot.remaining_percent === null ? 'Restmenge unbekannt' : number(slot.remaining_percent) + ' %' }}</p><p class="text-medium-emphasis">{{ time(slot.observed_at) }}{{ slot.manual_binding ? ' · manuell zugeordnet' : '' }}</p></v-card-text><v-card-actions><v-btn :disabled="busy || !slot.occupied" @click="binding = slot; bindingId = slot.spool_id">Rolle zuordnen</v-btn></v-card-actions></v-card></v-col></v-row></template>
    <template v-if="tab === 'settings'"><v-card title="Bambu-Cloud" class="mb-5"><v-card-text><v-alert type="info" variant="tonal" class="mb-4">Experimentelle interne Bambu-Schnittstelle. Lokal bleibt deine Sammlung vollständig nutzbar. Passwort und E-Mail-Code werden nicht gespeichert.</v-alert><p class="mb-3">{{ settings?.token_configured ? 'Anmeldung gespeichert' : 'Noch nicht verbunden' }} · Letzter Abgleich: {{ time(settings?.last_sync || null) }}</p><v-alert v-if="settings?.last_error" type="warning" class="mb-3">{{ settings.last_error }}</v-alert><v-select v-model="config.region" :items="[{title:'Global',value:'global'},{title:'China',value:'cn'}]" label="Region" /><v-text-field v-model="login.account" label="Bambu-E-Mail" autocomplete="username" /><v-text-field v-if="!verify" v-model="login.password" label="Passwort" type="password" autocomplete="new-password" /><v-text-field v-model="login.code" label="E-Mail-Code (falls angefordert)" autocomplete="one-time-code" /><v-expansion-panels variant="accordion" class="mb-3"><v-expansion-panel title="Alternativ: vorhandener Access Token"><v-expansion-panel-text><v-text-field v-model="login.access_token" type="password" label="Bambu Access Token" autocomplete="new-password" /></v-expansion-panel-text></v-expansion-panel></v-expansion-panels><div class="d-flex flex-wrap ga-3"><v-btn :disabled="busy" @click="connect">{{ verify ? 'Mit Code bestätigen' : 'Anmelden' }}</v-btn><v-btn :disabled="busy || !settings?.token_configured" @click="disconnect">Verbindung trennen</v-btn><v-btn :disabled="busy || !settings?.token_configured" @click="sync">Bestand jetzt abgleichen</v-btn></div></v-card-text></v-card>
      <v-card title="Abgleich und QR-Etiketten"><v-card-text><v-switch v-model="config.enabled" label="Automatischen Cloud-Abgleich aktivieren" color="primary" /><v-text-field v-model.number="config.interval_minutes" type="number" min="5" max="1440" label="Intervall in Minuten (5–1440)" /><v-switch v-model="config.mqtt_enabled" label="AMS-Snapshots über Cloud-MQTT mit abrufen" color="primary" /><v-textarea v-model="serialText" label="Druckerkennungen / Seriennummern (eine pro Zeile)" hint="Mehrere Drucker möglich; keine HA-Verbindung erforderlich. Drucker müssen online sein." persistent-hint /><v-text-field v-model="config.public_url" label="Öffentliche DocOfHome-Adresse für QR-Links" placeholder="https://zuhause.example.de" hint="Ohne Unterpfad. Muss beim Scannen auf dem Smartphone erreichbar sein." persistent-hint class="mt-3" /><p class="text-medium-emphasis my-4">Filamentgewichte sind übernommene oder geschätzte Werte, keine Waage. Cloud-Abgleich aktualisiert Restmengen; lokale Farbtexte, Shopnummer, Zustand, Notizen und Archiv bleiben erhalten. Etiketten: Phomemo M110, 40 × 30 mm, Druck ohne Skalierung.</p><label for="filament-json">Optional: bereinigten Cloud-Snapshot importieren (JSON, max. 8 MB)</label><input id="filament-json" type="file" accept="application/json,.json" class="d-block mt-2" :disabled="busy" @change="importFile" /></v-card-text><v-card-actions class="filament-save-bar"><span v-if="dirty">Ungespeicherte Änderungen</span><v-spacer /><v-btn :disabled="busy" @click="discardConfig">Verwerfen</v-btn><v-btn color="primary" :disabled="busy" @click="saveConfig">Einstellungen speichern</v-btn></v-card-actions></v-card>
    </template>
    <v-dialog :model-value="editor" persistent max-width="950"><v-card><v-card-title>{{ editing ? 'Filamentrolle bearbeiten' : 'Filamentrolle erfassen' }}</v-card-title><v-form @submit.prevent="save"><v-card-text><v-alert v-if="error" type="error" class="mb-3">{{ error }}</v-alert><v-row dense><v-col cols="12" sm="6"><v-combobox v-model="form.manufacturer" :items="manufacturers" label="Hersteller (z. B. SUNLU)" maxlength="100" /></v-col><v-col cols="12" sm="6"><v-combobox v-model="form.material" :items="materials" label="Material *" maxlength="100" /></v-col><v-col cols="12" sm="6"><v-text-field v-model="form.variant" label="Variante (z. B. PLA Basic)" maxlength="200" /></v-col><v-col cols="12" sm="6"><v-text-field v-model="form.color_name" label="Farbname" maxlength="200" /></v-col><v-col cols="12" sm="6"><v-text-field v-model="form.color_hex" label="Farbcode (#RRGGBB)" /></v-col><v-col cols="12" sm="6"><v-text-field v-model="form.shop_code" label="Bambu-Shop-Farbnummer (z. B. 10502)" maxlength="100" /></v-col><v-col cols="12" sm="6"><v-select v-model="form.condition" :items="[{title:'Eingepackt',value:'sealed'},{title:'Offen',value:'open'}]" label="Zustand" /></v-col><v-col cols="12" sm="6"><v-text-field v-model="form.rfid" label="RFID / technische Spulenkennung (optional)" hint="Null-Kennungen gelten als unbekannt." /></v-col><v-col cols="4"><v-text-field v-model.number="form.initial_g" type="number" label="Ursprünglich (g)" min="0" /></v-col><v-col cols="4"><v-text-field v-model.number="form.remaining_g" type="number" label="Verbleibend (g)" min="0" /></v-col><v-col cols="4"><v-text-field v-model.number="form.remaining_percent" type="number" label="Verbleibend (%)" min="0" max="100" /></v-col><v-col cols="12" sm="6"><v-select v-model="form.location_id" :items="locations" label="Lagerort" clearable /></v-col><v-col cols="12" sm="6"><v-text-field v-model="form.storage_note" label="Box / Regal / Lagerhinweis" maxlength="300" /></v-col><v-col cols="12"><v-checkbox v-model="form.reorder" label="Zum Nachbestellen markieren" /><v-text-field v-model="form.reorder_note" label="Nachbestellnotiz" maxlength="1000" /></v-col></v-row><ProductImageField v-model="form.image_url" :search-terms="`${form.manufacturer} ${form.variant} ${form.color_name}`" title="Rollenbild" /><v-textarea v-model="form.notes" label="Notizen" maxlength="50000" /></v-card-text><v-card-actions class="filament-save-bar"><span v-if="JSON.stringify(form) !== savedForm">Ungespeicherte Änderungen</span><v-spacer /><v-btn :disabled="busy" @click="closeEditor">Verwerfen / Schließen</v-btn><v-btn color="primary" type="submit" :loading="busy">Speichern</v-btn></v-card-actions></v-form></v-card></v-dialog>
    <v-dialog :model-value="!!detail" max-width="720" @update:model-value="v => { if (!v) detail = null }"><v-card v-if="detail"><v-card-title class="text-wrap">{{ detail.label_code }} · {{ detail.manufacturer }} {{ detail.variant || detail.material }}</v-card-title><v-card-text><v-img v-if="detail.image_url" :src="detail.image_url" contain height="200" /><p>{{ detail.color_name }} · {{ detail.color_hex }} · Shop: {{ detail.shop_code || 'nicht hinterlegt' }}</p><p>Zustand: {{ detail.condition === 'open' ? 'offen' : 'eingepackt' }} · {{ detail.archived_at ? 'archiviert' : 'aktiv' }}</p><p>Restgewicht: {{ detail.remaining_g === null ? 'unbekannt' : number(detail.remaining_g) + ' g' }}</p><p>Nachbestellen: {{ detail.reorder ? 'ja' : 'nein' }} · {{ detail.reorder_note }}</p><p>Lagerort: {{ detail.location_name || '–' }} · {{ detail.storage_note }}</p><p>Zuletzt im AMS erkannt: {{ time(detail.last_seen_at) }} (kein Drucknachweis)</p><p>Zuordnung aus {{ detail.mount_source || 'keiner Quelle' }} · {{ time(detail.mount_observed_at) }}</p><p>Cloud-ID: {{ detail.cloud_id || 'keine' }} · Produktcode: {{ detail.cloud_product_code || '–' }}</p><p>RFID: {{ detail.rfid || 'unbekannt' }}</p><p class="spool-notes mt-3">{{ detail.notes }}</p><a v-if="detail.image_source_url" :href="detail.image_source_url" target="_blank" rel="noopener noreferrer">Bildquelle im Store</a></v-card-text><v-card-actions class="flex-wrap"><v-btn @click="detail = null">Schließen</v-btn><v-btn @click="open(detail)">Bearbeiten</v-btn><v-btn :disabled="busy" @click="storeImage(detail)">Store-Farbbild suchen</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog :model-value="!!archiving" max-width="550" persistent><v-card><v-card-title>Rolle archivieren?</v-card-title><v-card-text>{{ archiving?.label_code }} bleibt mit Identitäten und Angaben erhalten.<v-checkbox v-if="archiving?.cloud_id" v-model="cloudDelete" label="Zusätzlich genau diese Rolle in der Bambu-Cloud löschen" /><v-alert v-if="cloudDelete" type="warning" variant="tonal">Die Cloud-Löschung ist dauerhaft. Das lokale Archiv bleibt erhalten.</v-alert><v-alert v-if="error" type="error">{{ error }}</v-alert></v-card-text><v-card-actions><v-btn :disabled="busy" @click="archiving = null">Abbrechen</v-btn><v-spacer /><v-btn color="primary" :loading="busy" @click="archiveNow">{{ cloudDelete ? 'Archivieren und Cloud-Rolle löschen' : 'Nur lokal archivieren' }}</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog :model-value="!!binding" persistent max-width="500"><v-card><v-card-title>AMS-Rolle zuordnen</v-card-title><v-card-text><p class="mb-3">Material und Farbe reichen bei gleichen Rollen nicht als Identität. Die manuelle Zuordnung gilt bis zum erkannten Wechsel der Slot-Kennung.</p><v-select v-model="bindingId" :items="active.map(v => ({title:v.label_code + ' · ' + v.manufacturer + ' ' + v.material + ' ' + v.color_name,value:v.id}))" label="Rolle" clearable /><v-alert v-if="error" type="error">{{ error }}</v-alert></v-card-text><v-card-actions><v-btn :disabled="busy" @click="binding = null">Abbrechen</v-btn><v-spacer /><v-btn :loading="busy" color="primary" @click="saveBinding">Zuordnen</v-btn></v-card-actions></v-card></v-dialog>
  </v-container>
</template>
